// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface DischargeSummaryViewOut {
  admission: SummaryAdmissionOut;
  /** Null until the first save */
  summary: DischargeSummaryOut | null;
  corrections: DischargeSummaryCorrectionOut[];
  suggested: DischargeSummarySuggestionOut;
  /** Fields signing still needs for the chosen outcome (e.g. receiving_hospital) */
  missing: string[];
}

export interface SummaryAdmissionOut {
  admission_id: number;
  admission_number: string;
  admission_status: "AdmissionPending" | "Waitlisted" | "BedReserved" | "CodeRedActive" | "Admitted" | "DischargeInProgress" | "Discharged" | "Cancelled";
  admission_type: "Standard" | "Emergency" | "CodeRed" | "Overflow" | "Planned";
  patient_id: number;
  mrn: string;
  patient_name: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  dob: string | null;
  requested_at: string;
  admitted_at: string | null;
  discharged_at: string | null;
  ward_name: string | null;
  bed_label: string | null;
  primary_doctor_name: string | null;
  admission_reason: string | null;
  provisional_diagnosis: string | null;
}

/** The discharge summary. Final = signed; the signer's stamp (name, designation, licence) is frozen at signing. */
export interface DischargeSummaryOut {
  summary_id: number;
  admission_id: number;
  patient_id: number;
  outcome: "Home" | "Transferred" | "LAMA" | "Absconded" | "Died";
  condition_at_discharge: "Recovered" | "Improved" | "Unchanged" | "Deteriorated" | null;
  reason_for_admission: string | null;
  final_diagnosis: string | null;
  icd_codes: string[];
  /** The codes with their titles and WHO URIs */
  icd_terms: IcdTermOut[];
  significant_findings: string | null;
  procedures_and_treatment: string | null;
  response_to_treatment: string | null;
  discharge_medications: string | null;
  follow_up_instructions: string | null;
  follow_up_date: string | null;
  receiving_hospital: string | null;
  transfer_reason: string | null;
  transfer_arrangements: string | null;
  outcome_note: string | null;
  status: "Draft" | "Final";
  created_by: number;
  created_by_name: string;
  created_at: string;
  signed_by: number | null;
  signed_at: string | null;
  signer_name: string | null;
  signer_designation: string | null;
  /** e.g. "PMDC 12345-P" */
  signer_license: string | null;
  row_version: number;
}

/** A code as stored in a record, with its title and WHO URI from the code list (the ICD-11 licence asks for code, title and URI together wherever codes are sent). `title` is null only for a code no list has. */
export interface IcdTermOut {
  code: string;
  system: "ICD-11" | "ICD-10";
  title: string | null;
  /** ICD-11: the WHO URI of the entity (null for ICD-10) */
  uri: string | null;
}

export interface DischargeSummaryCorrectionOut {
  correction_id: number;
  field: "reason_for_admission" | "final_diagnosis" | "significant_findings" | "procedures_and_treatment" | "response_to_treatment" | "discharge_medications" | "follow_up_instructions" | "transfer" | "general";
  correction_text: string;
  correction_reason: string;
  corrected_by_name: string;
  created_at: string;
}

/** A starting point from the stay's records, never saved by itself. */
export interface DischargeSummarySuggestionOut {
  /** Died when a death is recorded on this admission (then no other outcome can be signed) */
  outcome: "Home" | "Transferred" | "LAMA" | "Absconded" | "Died" | null;
  reason_for_admission: string | null;
  final_diagnosis: string | null;
  icd_codes: string[];
  /** The suggested codes with their titles and WHO URIs */
  icd_terms: IcdTermOut[];
  /** Abnormal results with value and flag, normal tests, imaging reports */
  significant_findings: string | null;
  /** Operations and the medicines given (from the MAR) */
  procedures_and_treatment: string | null;
  /** Active oral / topical prescription lines */
  discharge_medications: string | null;
}

/** Only the fields sent change. Send row_version as expected_version once the draft exists. */
export interface DischargeSummaryIn {
  outcome?: "Home" | "Transferred" | "LAMA" | "Absconded" | "Died" | null;
  condition_at_discharge?: "Recovered" | "Improved" | "Unchanged" | "Deteriorated" | null;
  reason_for_admission?: string | null;
  final_diagnosis?: string | null;
  icd_codes?: string[] | null;
  significant_findings?: string | null;
  procedures_and_treatment?: string | null;
  response_to_treatment?: string | null;
  /** Write "None" when nothing is prescribed */
  discharge_medications?: string | null;
  follow_up_instructions?: string | null;
  follow_up_date?: string | null;
  /** Outcome Transferred */
  receiving_hospital?: string | null;
  transfer_reason?: string | null;
  /** Escort, ambulance, oxygen, handover call */
  transfer_arrangements?: string | null;
  /** Outcome LAMA / Absconded: the circumstances */
  outcome_note?: string | null;
  expected_version?: number | null;
}

export interface SignIn {
  /** row_version of the draft you read */
  expected_version?: number | null;
}

export interface SummaryCorrectionIn {
  field?: "reason_for_admission" | "final_diagnosis" | "significant_findings" | "procedures_and_treatment" | "response_to_treatment" | "discharge_medications" | "follow_up_instructions" | "transfer" | "general";
  correction_text: string;
  correction_reason: string;
}

