/** The discharge summary, what the stay suggests, and what is still missing — GET /api/v1/admissions/{admission_id}/discharge-summary (who may call: holders of ipd.discharge.initiate or clinical.encounter.view or patient.emr.view). */
export function getDischargeSummary(admission_id: number): Promise<DischargeSummaryViewOut> {
  return api<DischargeSummaryViewOut>("GET", `/admissions/${admission_id}/discharge-summary`, undefined);
}

/** Save the discharge summary draft — PUT /api/v1/admissions/{admission_id}/discharge-summary (who may call: holders of ipd.discharge.initiate). */
export function saveDischargeSummary(admission_id: number, body: DischargeSummaryIn): Promise<DischargeSummaryViewOut> {
  return api<DischargeSummaryViewOut>("PUT", `/admissions/${admission_id}/discharge-summary`, body);
}

/** Sign the discharge summary (final) — POST /api/v1/admissions/{admission_id}/discharge-summary/sign (who may call: holders of ipd.discharge.initiate). */
export function signDischargeSummary(admission_id: number, body: SignIn): Promise<DischargeSummaryViewOut> {
  return api<DischargeSummaryViewOut>("POST", `/admissions/${admission_id}/discharge-summary/sign`, body);
}

/** Append a correction to a signed discharge summary — POST /api/v1/admissions/{admission_id}/discharge-summary/corrections (who may call: holders of ipd.discharge.initiate). */
export function correctDischargeSummary(admission_id: number, body: SummaryCorrectionIn): Promise<DischargeSummaryViewOut> {
  return api<DischargeSummaryViewOut>("POST", `/admissions/${admission_id}/discharge-summary/corrections`, body, { idempotent: true });
}

/** Printable discharge summary, or referral slip for a transfer — GET /api/v1/admissions/{admission_id}/discharge-summary/print-payload (who may call: holders of ipd.discharge.initiate or clinical.encounter.view or patient.emr.view). */
export function dischargeSummaryPrint(admission_id: number): Promise<PrintOut_DischargeSummaryPrintFieldsOut_> {
  return api<PrintOut_DischargeSummaryPrintFieldsOut_>("GET", `/admissions/${admission_id}/discharge-summary/print-payload`, undefined);
}

/** The signed discharge summary as a PDF — GET /api/v1/admissions/{admission_id}/discharge-summary/pdf (who may call: holders of ipd.discharge.initiate or clinical.encounter.view or patient.emr.view). */
export function dischargeSummaryPdf(admission_id: number): Promise<unknown> {
  return api<unknown>("GET", `/admissions/${admission_id}/discharge-summary/pdf`, undefined);
}

/** ICD picker: search codes by code or words — GET /api/v1/icd/codes (who may call: any logged-in user). */
export function searchIcdCodes(query: { q: string; system?: "ICD-11" | "ICD-10" | null; limit?: number }): Promise<IcdSearchOut> {
  return api<IcdSearchOut>("GET", withQuery(`/icd/codes`, query), undefined);
}

/** ICD picker: browse chapters, blocks, categories — GET /api/v1/icd/browse (who may call: any logged-in user). */
export function browse(query?: { parent?: string | null; system?: "ICD-11" | "ICD-10" | null }): Promise<IcdBrowseOut> {
  return api<IcdBrowseOut>("GET", withQuery(`/icd/browse`, query), undefined);
}

/** One ICD code with its place in the tree — GET /api/v1/icd/codes/{code} (who may call: any logged-in user). */
export function detail(code: string, query?: { system?: "ICD-11" | "ICD-10" | null }): Promise<IcdDetailOut> {
  return api<IcdDetailOut>("GET", withQuery(`/icd/codes/${code}`, query), undefined);
}

/** The ICD code lists loaded — GET /api/v1/icd/releases (who may call: any logged-in user). */
export function releases(): Promise<IcdReleasesOut> {
  return api<IcdReleasesOut>("GET", `/icd/releases`, undefined);
}
